{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "A direct human absolute-bioavailability study of an amidinophenyl carboxylate analogue found it 'not high enough for oral use', supporting low F for the query's amidine/carboxylate zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Avoralstat, which shares the amidinophenyl amide and pyridine-carboxylate motifs, was reported to have low oral bioavailability in patients, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Disopyramide has about 80% absolute oral bioavailability in humans, but it lacks the acidic/zwitterionic groups of the query, so this high-F evidence is only weakly contradictory.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C32"],
      "claim": "Folic acid has about 76% absolute bioavailability in humans, but this is transporter-mediated and the query lacks the folate scaffold, making it weakly contradictory.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Low oral bioavailability is predicted: the query is a fully ionized zwitterion with very low logD and high TPSA, and the most structurally relevant amidine/carboxylate-containing analogues show low or inadequate oral bioavailability in humans. High-bioavailability analogues are either too dissimilar or depend on active transport, so they do not outweigh the low-F evidence.",
  "evidence_gaps": [
    "No direct absolute F measurement for the query or a close analogue; all Morgan similarities are below 0.3.",
    "No information on whether the query is a substrate for absorptive transporters that could overcome poor passive permeability.",
    "No human PK data for the exact benzimidazole-amidine-pyridinecarboxamide scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

